'use strict';
const $=s=>document.querySelector(s);let cards=[],guide=[],spreads=[],filter='all',query='',visible=[],current=null,saved=new Set();try{saved=new Set(JSON.parse(localStorage.getItem('lilifer-favorites')||'[]'))}catch{}
const names={major:'大アルカナ',extra:'特別なカード',wands:'ワンド',cups:'カップ',swords:'ソード',pentacles:'ペンタクル'};
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>s.normalize('NFKC').toLowerCase().replace(/[\u30a1-\u30f6]/g,c=>String.fromCharCode(c.charCodeAt(0)-0x60)).replace(/[\s・ー]/g,'');
function render(){const q=normalize(query);visible=cards.filter(c=>(filter==='all'||c.group===filter||(filter==='saved'&&saved.has(c.id)))&&normalize([c.name,c.en,c.reading,c.up,c.down,c.number,c.body||''].join(' ')).includes(q));$('#count').textContent=`${visible.length} / 80 枚`;$('#grid').innerHTML=visible.map(c=>`<button class="card" data-id="${c.id}" aria-label="${esc(c.name)}の解説を読む"><span class="card-image"><img src="${c.image}" alt="${esc(c.name)}のカード" loading="lazy" width="150" height="250"></span>${saved.has(c.id)?'<span class="saved-dot" aria-hidden="true">♥</span>':''}<span class="card-num">${c.number} · ${names[c.group]}</span><h3>${c.name}</h3><span class="card-en">${c.en.toUpperCase()}</span><span class="card-key">${c.up.split('、').slice(0,2).join('・')}</span></button>`).join('');$('#empty').hidden=visible.length>0;$('#clear-search').hidden=!query}
function setFilter(f){filter=f;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===f);b.setAttribute('aria-pressed',b.dataset.filter===f)});render()}
function source(page){return `<details class="original"><summary>原文を見る · PDF ${page}ページ</summary><img src="original/${page}.webp" alt="原著の${page}ページ" loading="lazy"></details>`}
function openCard(id,update=true){const c=cards.find(c=>c.id===id);if(!c)return;current=id;$('#detail-index').textContent=`${names[c.group]} / ${c.number}`;$('#detail-content').innerHTML=`<div class="detail-layout"><div class="detail-visual"><img src="${c.image}" alt="${c.name}のカード"><button class="favorite" id="favorite" aria-pressed="${saved.has(id)}">${saved.has(id)?'♥ お気に入りに保存済み':'♡ お気に入りに追加'}</button></div><article><header class="detail-heading"><p>${c.number} · ${c.en.toUpperCase()}</p><h2 id="detail-title">${c.name}</h2><small>${c.reading}</small></header><div class="meanings">${c.same?`<p class="notice">正位置・逆位置で意味は変わりません。</p><div class="meaning"><h3>共通のキーワード</h3><p>${c.up}</p></div><p class="body-text">${esc(c.body)}</p>`:`<section class="meaning"><h3>↑ 正位置</h3><p>${c.up}</p></section><section class="meaning reversed"><h3>↓ 逆位置</h3><p>${c.down}</p></section>`}</div>${c.affirm?`<p class="affirm"><small>AFFIRMATION · 自分に贈る言葉</small>${c.affirm}</p>`:''}${c.element?`<details class="correspondences"><summary>元素${c.planet?'・惑星・石・植物':''}の対応</summary><dl>${[['元素',c.element],['惑星',c.planet],['星座',c.zodiac],['石など',c.stones],['植物など',c.herbs]].filter(x=>x[1]).map(x=>`<div><dt>${x[0]}</dt><dd>${x[1]}</dd></div>`).join('')}</dl>${c.herbs?'<p class="notice">原著の象徴上の対応です。植物や物質の摂取・使用を勧めるものではありません。</p>':''}</details>`:''}<p class="source-label">出典：The Lilifer Tarot · PDF ${c.page}ページ<br>原著のキーワードを日本語に翻訳しています。</p>${source(c.page)}</article></div>`;$('#favorite').onclick=()=>{saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem('lilifer-favorites',JSON.stringify([...saved]))}catch{}$('#favorite').setAttribute('aria-pressed',saved.has(id));$('#favorite').textContent=saved.has(id)?'♥ お気に入りに保存済み':'♡ お気に入りに追加';render()};const i=cards.indexOf(c);$('#prev').disabled=i===0;$('#next').disabled=i===cards.length-1;$('#detail-position').textContent=`${i+1} / 80`;if(!$('#detail').open){$('#detail').showModal();document.body.classList.add('modal-open')}$('#detail').scrollTop=0;if(update)history.replaceState(null,'',`#card-${id}`)}
function closeCard(){if($('#detail').open)$('#detail').close()}
$('#detail').addEventListener('close',()=>{document.body.classList.remove('modal-open');if(location.hash.startsWith('#card-'))history.replaceState(null,'','#catalog');current=null});$('#close').onclick=closeCard;$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeCard()}});
$('#prev').onclick=()=>openCard(cards[cards.findIndex(c=>c.id===current)-1]?.id);$('#next').onclick=()=>openCard(cards[cards.findIndex(c=>c.id===current)+1]?.id);
$('#grid').onclick=e=>{const b=e.target.closest('[data-id]');if(b)openCard(b.dataset.id)};
$('#search').oninput=e=>{query=e.target.value;render()};$('#clear-search').onclick=()=>{query='';$('#search').value='';render();$('#search').focus()};$('#reset').onclick=()=>{query='';$('#search').value='';setFilter('all')};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>setFilter(b.dataset.filter));
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{const tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});document.querySelectorAll('.view').forEach(x=>x.hidden=x.id!==tab+'-view')});
async function init(){try{[cards,guide,spreads]=await Promise.all(['cards','guide','spreads'].map(async n=>{const r=await fetch(n+'.json');if(!r.ok)throw Error(n);return r.json()}));render();$('#guides').innerHTML=guide.map((g,i)=>`<details${i===0?' open':''}><summary>${g.title}</summary><div class="guide-inner"><p>${g.intro}</p><dl>${g.rows.map(r=>`<div><dt>${r[0]}</dt><dd>${r[1]}</dd></div>`).join('')}</dl>${g.pages.map(source).join('')}</div></details>`).join('');$('#spreads').innerHTML=spreads.map((s,i)=>`<article class="spread"><header><span>0${i+1}</span><h3>${s[0]}</h3></header><p class="eyebrow">${s[1]} · ${s[4].length} CARDS</p><div class="spread-body"><div class="spread-map" role="img" aria-label="${s[0]}のカード配置。番号順にカードを並べます。">${s[5].map((xy,j)=>`<span class="spread-card" style="left:${xy[0]}%;top:${xy[1]}%">${j+1}</span>`).join('')}</div><div><p>${s[3]}</p><ol>${s[4].map(x=>`<li>${x}</li>`).join('')}</ol>${source(s[2])}</div></div></article>`).join('');if(location.hash.startsWith('#card-'))openCard(location.hash.slice(6),false)}catch(e){$('#count').textContent='読み込みに失敗しました。ページを再読み込みしてください。';console.error(e)}}init();
